-- STEP BOUNDARY --

-- STEP 3: query [arealressurskart_ar50]
SELECT DISTINCT arveget, artreslag, artype FROM public."0000_25833_ar50_gdb__ar50" WHERE ST_Intersects(wkb_geometry, (SELECT omrade FROM kommuner_627ee106072240e99d2b21ec4717bf01.kommune WHERE kommunenummer = '4601')) LIMIT 200;

